#!/bin/sh
# Generated by FWShift - review the conversion report before running this.
#
# Check Point Management API calls (mgmt_cli): objects, the rules of access layer
# 'Network' and the NAT rules of policy package 'Standard'.
#
# 1. Log in and keep the session in a file:
#        mgmt_cli login -r true > fwshift.sid          (as root on the management server)
#        mgmt_cli login user <admin> > fwshift.sid     (anywhere else; add -m <server>)
# 2. Run this script:  sh <this file>
# 3. Look at the session in SmartConsole. Nothing is published or installed here:
#        mgmt_cli publish -s fwshift.sid       to keep the changes
#        mgmt_cli discard -s fwshift.sid       to throw them away
#
# The script stops at the first call the server refuses. Discard the session, fix
# the cause and run it again: a policy with rules missing is not a safe policy.
#
# SID        session file (default fwshift.sid)
# MGMT_OPTS  extra switches for every call, for example: MGMT_OPTS='-m 192.0.2.10'

SID="${SID:-fwshift.sid}"

m() {
    if ! out=$(mgmt_cli "$@" $MGMT_OPTS -s "$SID" 2>&1); then
        printf 'FAILED: mgmt_cli %s\n%s\n' "$*" "$out" >&2
        printf 'Stopped. Nothing was published. Undo with: mgmt_cli discard -s %s\n' "$SID" >&2
        exit 1
    fi
}

# A zone has no content of its own: one that exists already is used as it is.
zone() {
    mgmt_cli show security-zone name "$1" $MGMT_OPTS -s "$SID" >/dev/null 2>&1 || m add security-zone name "$1" ignore-warnings true
}

# Network objects
m add address-range name internet ip-address-first 0.0.0.0 ip-address-last 255.255.255.255 ignore-warnings true
m add address-range name internet6 ip-address-first :: ip-address-last ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff ignore-warnings true
m add network name internal-network subnet 192.168.10.0 mask-length 24 comments 'the networks of interface eth1' ignore-warnings true
m add host name internal-interface ip-address 192.168.10.1 comments 'the address of interface eth1' ignore-warnings true
m add host name external-interface ip-address 203.0.113.2 comments 'the address of interface eth0' ignore-warnings true
m add network name dmz1-network subnet 172.16.20.0 mask-length 24 comments 'the networks of interface eth2' ignore-warnings true
m add host name public-mail ip-address 203.0.113.5 ignore-warnings true
m add host name webserver ip-address 172.16.20.10 ignore-warnings true
m add host name mailserver ip-address 172.16.20.25 ignore-warnings true
m add host name admin-pc ip-address 192.168.10.50 ignore-warnings true
m add address-range name printers ip-address-first 192.168.10.200 ip-address-last 192.168.10.220 ignore-warnings true
m add network name lan6 subnet 2001:db8:10:: mask-length 64 ignore-warnings true
m add network name partner-net subnet 10.20.0.0 mask-length 16 ignore-warnings true
m add dns-domain name .updates.example.com is-sub-domain false ignore-warnings true
m add group name blocked-region comments 'FWSHIFT PLACEHOLDER, matches nothing: address '\''geoip:XX'\'' is not a form FWShift reads' ignore-warnings true
m add group name servers members.1 webserver members.2 mailserver ignore-warnings true
m add group name admins-and-partner members.1 admin-pc members.2 partner-net ignore-warnings true

# Services
m add service-tcp name http port 80 match-for-any false ignore-warnings true
m add service-tcp name https port 443 match-for-any false ignore-warnings true
m add service-tcp name extern-https port 8443 match-for-any false ignore-warnings true
m add service-tcp name smtp port 25 match-for-any false ignore-warnings true
m add service-udp name domain-udp port 53 match-for-any false ignore-warnings true
m add service-udp name ntp-client port 123 source-port 1024-65535 match-for-any false ignore-warnings true
m add service-tcp name app-ports port 8000-8010 match-for-any false ignore-warnings true
m add service-icmp name icmp-echo-req icmp-type 8 ignore-warnings true
m add service-icmp6 name icmpv6-echo icmp-type 128 ignore-warnings true
m add service-other name gre ip-protocol 47 match-for-any false ignore-warnings true
m add service-tcp name ftp port 21 match-for-any false comments 'connection tracking helper ftp' ignore-warnings true
m add service-tcp name ssh port 22 match-for-any false comments 'a service the UTM comes with' ignore-warnings true
m add service-group name web members.1 http members.2 https ignore-warnings true
m add service-group name default-internet members.1 http members.2 https members.3 domain-udp members.4 icmp-echo-req members.5 ftp ignore-warnings true

# Security zones
zone internal
zone external
zone vpn-ipsec
zone dmz1

# Traffic from zone internal to zone external
m add access-layer name Network_internal_to_external add-default-rule false ignore-warnings true
m add access-rule layer Network_internal_to_external position bottom name rule-1 source.1 internal-network destination.1 internet service.1 default-internet action Accept track.type Log comments 'LAN to the internet' ignore-warnings true
m add access-rule layer Network_internal_to_external position bottom name rule-4 source.1 lan6 destination.1 internet6 service.1 web action Accept track.type None comments 'LAN IPv6 web' ignore-warnings true
m add access-rule layer Network_internal_to_external position bottom name rule-11 source.1 internal-network destination.1 .updates.example.com service.1 https action Accept track.type None ignore-warnings true
m add access-rule layer Network_internal_to_external position bottom name rule-13 source.1 admin-pc destination.1 Any service.1 icmp-echo-req action Accept track.type None comments 'ping from the admin' ignore-warnings true
m add access-rule layer Network_internal_to_external position bottom name rule-15 source.1 lan6 destination.1 internet6 service.1 icmpv6-echo action Accept track.type None ignore-warnings true
m add access-rule layer Network_internal_to_external position bottom name rule-3 source.1 printers destination.1 internet service.1 Any action Drop track.type None comments 'printers stay inside' ignore-warnings true
m add access-rule layer Network_internal_to_external position bottom name rule-9 source.1 internal-network destination.1 blocked-region service.1 Any action Drop track.type Log enabled false comments 'FWSHIFT: disabled by the converter, see the report. a region' ignore-warnings true
m add access-rule layer Network_internal_to_external position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 1 name 'internal to external' source.1 internal destination.1 external service.1 Any action 'Apply Layer' inline-layer Network_internal_to_external ignore-warnings true

# Traffic from zone internal to zone vpn-ipsec
m add access-layer name Network_internal_to_vpn-ipsec add-default-rule false ignore-warnings true
m add access-rule layer Network_internal_to_vpn-ipsec position bottom name rule-13 source.1 admin-pc destination.1 Any service.1 icmp-echo-req action Accept track.type None comments 'ping from the admin' ignore-warnings true
m add access-rule layer Network_internal_to_vpn-ipsec position bottom name rule-14 source.1 internal-network destination.1 partner-net service.1 ntp-client action Accept track.type None enabled false comments 'FWSHIFT: disabled by the converter, see the report.' ignore-warnings true
m add access-rule layer Network_internal_to_vpn-ipsec position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 2 name 'internal to vpn-ipsec' source.1 internal destination.1 vpn-ipsec service.1 Any action 'Apply Layer' inline-layer Network_internal_to_vpn-ipsec ignore-warnings true

# Traffic from zone internal to zone dmz1
m add access-layer name Network_internal_to_dmz1 add-default-rule false ignore-warnings true
m add access-rule layer Network_internal_to_dmz1 position bottom name rule-13 source.1 admin-pc destination.1 Any service.1 icmp-echo-req action Accept track.type None comments 'ping from the admin' ignore-warnings true
m add access-rule layer Network_internal_to_dmz1 position bottom name rule-7 source.1 admin-pc destination.1 servers service.1 ssh action Accept track.type Log comments administration ignore-warnings true
m add access-rule layer Network_internal_to_dmz1 position bottom name rule-12 source.1 internal-network destination.1 dmz1-network service.1 app-ports action Accept track.type None ignore-warnings true
m add access-rule layer Network_internal_to_dmz1 position bottom name rule-16 source.1 internal-network destination.1 webserver service.1 gre action Accept track.type None enabled false comments 'FWSHIFT: disabled by the converter, see the report.' ignore-warnings true
m add access-rule layer Network_internal_to_dmz1 position bottom name rule-17 source.1 internal-network destination.1 mailserver service.1 smtp action Drop track.type None comments 'only the mail server sends' ignore-warnings true
m add access-rule layer Network_internal_to_dmz1 position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 3 name 'internal to dmz1' source.1 internal destination.1 dmz1 service.1 Any action 'Apply Layer' inline-layer Network_internal_to_dmz1 ignore-warnings true

# Traffic from zone external to zone dmz1
m add access-layer name Network_external_to_dmz1 add-default-rule false ignore-warnings true
m add access-rule layer Network_external_to_dmz1 position bottom name rule-18 source.1 internet destination.1 webserver destination.2 external-interface service.1 https action Drop track.type None comments 'a rule above the forward sees the server' ignore-warnings true
m add access-rule layer Network_external_to_dmz1 position bottom name rule-2 source.1 internet destination.1 external-interface service.1 extern-https action Accept track.type Log comments 'publish the web server' ignore-warnings true
m add access-rule layer Network_external_to_dmz1 position bottom name rule-6 source.1 internet destination.1 public-mail service.1 smtp action Accept track.type None comments 'publish the mail server' ignore-warnings true
m add access-rule layer Network_external_to_dmz1 position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 4 name 'external to dmz1' source.1 external destination.1 dmz1 service.1 Any action 'Apply Layer' inline-layer Network_external_to_dmz1 ignore-warnings true

# Traffic from zone vpn-ipsec to zone internal
m add access-layer name Network_vpn-ipsec_to_internal add-default-rule false ignore-warnings true
m add access-rule layer Network_vpn-ipsec_to_internal position bottom name rule-10 source.1 partner-net destination.1 internal-network service.1 Any action Accept track.type None comments 'VPN partner, not hidden' ignore-warnings true
m add access-rule layer Network_vpn-ipsec_to_internal position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 5 name 'vpn-ipsec to internal' source.1 vpn-ipsec destination.1 internal service.1 Any action 'Apply Layer' inline-layer Network_vpn-ipsec_to_internal ignore-warnings true

# Traffic from zone vpn-ipsec to zone dmz1
m add access-layer name Network_vpn-ipsec_to_dmz1 add-default-rule false ignore-warnings true
m add access-rule layer Network_vpn-ipsec_to_dmz1 position bottom name rule-7-2 source.1 partner-net destination.1 servers service.1 ssh action Accept track.type Log comments administration ignore-warnings true
m add access-rule layer Network_vpn-ipsec_to_dmz1 position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 6 name 'vpn-ipsec to dmz1' source.1 vpn-ipsec destination.1 dmz1 service.1 Any action 'Apply Layer' inline-layer Network_vpn-ipsec_to_dmz1 ignore-warnings true

# Traffic from zone dmz1 to zone external
m add access-layer name Network_dmz1_to_external add-default-rule false ignore-warnings true
m add access-rule layer Network_dmz1_to_external position bottom name rule-8 source.1 dmz1-network destination.1 internet service.1 Any action Accept track.type None ignore-warnings true
m add access-rule layer Network_dmz1_to_external position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 7 name 'dmz1 to external' source.1 dmz1 destination.1 external service.1 Any action 'Apply Layer' inline-layer Network_dmz1_to_external ignore-warnings true

# Traffic from zone internal to zone (any other)
m add access-layer name Network_internal_to_any add-default-rule false ignore-warnings true
m add access-rule layer Network_internal_to_any position bottom name rule-13 source.1 admin-pc destination.1 Any service.1 icmp-echo-req action Accept track.type None comments 'ping from the admin' ignore-warnings true
m add access-rule layer Network_internal_to_any position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 8 name 'internal to any' source.1 internal destination.1 Any service.1 Any action 'Apply Layer' inline-layer Network_internal_to_any ignore-warnings true

# Rules of layer Network for traffic of no zone pair above
m add access-rule layer Network position 9 name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true

# NAT rules of package Standard
m add nat-rule package Standard position bottom original-source partner-net original-destination internal-network original-service Any translated-source Original translated-destination Original translated-service Original method static comments 'rule-10-nat: HIDENAT_EXCLUDE of rule-10' ignore-warnings true
m add nat-rule package Standard position bottom original-source internet original-destination external-interface original-service extern-https translated-source Original translated-destination webserver translated-service https method static comments 'rule-2-nat: DESTNAT of rule-2' ignore-warnings true
m add nat-rule package Standard position bottom original-source internet original-destination public-mail original-service smtp translated-source Original translated-destination mailserver translated-service Original method static comments 'rule-6-nat: DESTNAT of rule-6' ignore-warnings true
m add nat-rule package Standard position bottom original-source dmz1-network original-destination internet original-service Any translated-source external-interface translated-destination Original translated-service Original method hide comments 'rule-8-nat: HIDENAT of rule-8' ignore-warnings true

echo 'Done. Review the session, then publish or discard it.'
